/* HabitForge 纯函数内核：习惯数据模型 + 连击/完成率/热力图（无 DOM 依赖） */
var HF = (function(){
  'use strict';
  function pad2(n){ return (n<10?'0':'')+n; }
  function isLeap(y){ return (y%4===0 && y%100!==0) || y%400===0; }
  var DIM = [31,28,31,30,31,30,31,31,30,31,30,31];
  function dim(y,m){ return m===2 && isLeap(y) ? 29 : DIM[m-1]; }
  function toSerial(y,m,d){
    var yy = y - (m<=2?1:0), era = Math.floor(yy/400), yoe = yy - era*400;
    var doy = Math.floor((153*(m+(m>2?-3:9))+2)/5)+d-1;
    var doe = yoe*365 + Math.floor(yoe/4) - Math.floor(yoe/100) + doy;
    return era*146097 + doe - 719468;
  }
  function fromSerial(n){
    var z = n+719468, era = Math.floor(z/146097), doe = z-era*146097;
    var yoe = Math.floor((doe - Math.floor(doe/1460) + Math.floor(doe/36524) - Math.floor(doe/146096))/365);
    var y = yoe + era*400, doy = doe - (365*yoe + Math.floor(yoe/4) - Math.floor(yoe/100));
    var mp = Math.floor((5*doy+2)/153), d = doy - Math.floor((153*mp+2)/5) + 1, m = mp + (mp<10?3:-9);
    return { y: y + (m<=2?1:0), m:m, d:d };
  }
  function keyOf(o){ return o.y+'-'+pad2(o.m)+'-'+pad2(o.d); }
  function parseKey(k){
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(k||'');
    if(!m) return null;
    var o = { y:+m[1], m:+m[2], d:+m[3] };
    if(o.m<1||o.m>12||o.d<1||o.d>dim(o.y,o.m)) return null;
    return o;
  }
  function serialOfKey(k){ var o = parseKey(k); return o ? toSerial(o.y,o.m,o.d) : null; }
  function keyOfSerial(n){ return keyOf(fromSerial(n)); }

  /* ---- 数据模型 ---- */
  function makeState(){ return { habits: [], nextId: 1 }; }
  function addHabit(state, name){
    name = String(name||'').trim();
    if(!name) return null;
    var h = { id: state.nextId++, name: name, days: {} };  /* days: {"2026-07-27": 1} */
    state.habits.push(h);
    return h;
  }
  function removeHabit(state, id){
    var i = state.habits.findIndex(function(h){ return h.id === id; });
    if(i < 0) return false;
    state.habits.splice(i,1);
    return true;
  }
  function findHabit(state, id){
    for(var i=0;i<state.habits.length;i++) if(state.habits[i].id===id) return state.habits[i];
    return null;
  }
  function toggle(state, id, key){
    var h = findHabit(state, id);
    if(!h || serialOfKey(key)===null) return null;
    if(h.days[key]) delete h.days[key];
    else h.days[key] = 1;
    return !!h.days[key];
  }
  function isDone(h, key){ return !!(h && h.days && h.days[key]); }

  /* ---- 统计 ---- */
  /* 当前连击：从 refKey 往前数连续天；refKey 当天未打卡则看昨天起算 */
  function currentStreak(h, refKey){
    var s = serialOfKey(refKey);
    if(s===null || !h) return 0;
    if(!h.days[keyOfSerial(s)]) s -= 1;   /* 今天还没打卡不清零，从昨天算 */
    var n = 0;
    while(h.days[keyOfSerial(s)]){ n++; s--; }
    return n;
  }
  function longestStreak(h){
    if(!h) return 0;
    var ks = Object.keys(h.days).map(serialOfKey).filter(function(x){ return x!==null; }).sort(function(a,b){ return a-b; });
    var best = 0, cur = 0, prev = null;
    for(var i=0;i<ks.length;i++){
      if(prev!==null && ks[i]===prev+1) cur++;
      else cur = 1;
      if(cur>best) best = cur;
      prev = ks[i];
    }
    return best;
  }
  function totalDone(h){ return h ? Object.keys(h.days).length : 0; }
  /* 完成率：最近 n 天（含 refKey 当天） */
  function rate(h, refKey, n){
    var s = serialOfKey(refKey);
    if(s===null || !h || n<=0) return 0;
    var cnt = 0;
    for(var i=0;i<n;i++) if(h.days[keyOfSerial(s-i)]) cnt++;
    return Math.round(cnt/n*1000)/10;
  }
  /* 热力图数据：过去 weeks 周（对齐到 refKey 所在周的周日结尾），返回列数组 [{key,level,inRange}] */
  function heatCells(h, refKey, weeks){
    var s = serialOfKey(refKey);
    if(s===null) return [];
    weeks = weeks || 26;
    var dow = ((s+3)%7+7)%7;          /* 0=周一…6=周日 */
    var end = s + (6-dow);            /* 本周周日 */
    var start = end - weeks*7 + 1;
    var cells = [];
    for(var n=start;n<=end;n++){
      cells.push({ key: keyOfSerial(n), done: !!(h && h.days[keyOfSerial(n)]), future: n>s });
    }
    return cells;                     /* 长度 = weeks*7，按列（周）切片 */
  }
  /* ---- 序列化 ---- */
  function exportJSON(state){
    return JSON.stringify({ app:'HabitForge', version:1, habits: state.habits, nextId: state.nextId });
  }
  function importJSON(str){
    var o;
    try { o = JSON.parse(str); } catch(e){ return null; }
    if(!o || o.app!=='HabitForge' || !Array.isArray(o.habits)) return null;
    var st = makeState();
    var maxId = 0;
    for(var i=0;i<o.habits.length;i++){
      var h = o.habits[i];
      if(!h || typeof h.name!=='string' || !h.name.trim()) continue;
      var days = {};
      if(h.days && typeof h.days==='object'){
        for(var k in h.days){ if(serialOfKey(k)!==null && h.days[k]) days[k] = 1; }
      }
      var id = (typeof h.id==='number' && h.id>0) ? Math.floor(h.id) : (maxId+1);
      st.habits.push({ id:id, name:h.name.trim(), days:days });
      if(id>maxId) maxId = id;
    }
    st.nextId = Math.max(maxId+1, (typeof o.nextId==='number' && o.nextId>maxId) ? Math.floor(o.nextId) : maxId+1);
    return st;
  }
  function todayKey(){
    var d = new Date();
    return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());
  }
  return {
    pad2:pad2, dim:dim, toSerial:toSerial, fromSerial:fromSerial,
    keyOf:keyOf, parseKey:parseKey, serialOfKey:serialOfKey, keyOfSerial:keyOfSerial,
    makeState:makeState, addHabit:addHabit, removeHabit:removeHabit, findHabit:findHabit,
    toggle:toggle, isDone:isDone,
    currentStreak:currentStreak, longestStreak:longestStreak, totalDone:totalDone, rate:rate,
    heatCells:heatCells, exportJSON:exportJSON, importJSON:importJSON, todayKey:todayKey
  };
})();
if(typeof module!=='undefined' && module.exports){ module.exports = HF; }
if(typeof window!=='undefined'){ window.__HABITFORGE__ = HF; }
